#include <stdio.h>

typedef struct { int major, minor, patch; } Semver;

int semver_parse(Semver *v, char *s) {
    return sscanf(s, "%d.%d.%d", &v->major, &v->minor, &v->patch) == 3;
}

int semver_cmp(Semver *a, Semver *b) {
    if (a->major != b->major) return a->major < b->major ? -1 : 1;
    if (a->minor != b->minor) return a->minor < b->minor ? -1 : 1;
    if (a->patch != b->patch) return a->patch < b->patch ? -1 : 1;
    return 0;
}

int main() {
    Semver a, b;
    semver_parse(&a, "1.2.3");
    semver_parse(&b, "1.10.0");
    printf("A: %d.%d.%d\n", a.major, a.minor, a.patch);
    printf("B: %d.%d.%d\n", b.major, b.minor, b.patch);
    printf("Compare: %d\n", semver_cmp(&a, &b));
    return 0;
}
